"""Three layer-sweep panels; all visual elements are generated by matplotlib."""
from pathlib import Path
import argparse
import csv
import json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle

ROOT = Path(__file__).resolve().parent
COLOR = '#375b89'
BACKGROUND = '#f3f8fb'
GRID = '#e3edf3'

def smooth_curve(x,y,n=800):
    """Shape-preserving cubic (PCHIP) interpolation through every data point."""
    h=np.diff(x); delta=np.diff(y)/h; m=len(y); d=np.zeros(m)
    for k in range(1,m-1):
        if delta[k-1]*delta[k]<=0:
            d[k]=0.0
        else:
            w1=2*h[k]+h[k-1]; w2=h[k]+2*h[k-1]
            d[k]=(w1+w2)/(w1/delta[k-1]+w2/delta[k])
    for k,(h0,h1,d0,d1) in enumerate([(h[0],h[1],delta[0],delta[1]),
                                      (h[-1],h[-2],delta[-1],delta[-2])]):
        s=((2*h0+h1)*d0-h0*d1)/(h0+h1)
        if s*d0<=0: s=0.0
        elif d0*d1<0 and abs(s)>3*abs(d0): s=3*d0
        d[0 if k==0 else -1]=s
    per=max(2,n//(m-1))
    xs=np.concatenate([np.linspace(x[i],x[i+1],per,endpoint=False) for i in range(m-1)]+[[x[-1]]])
    i=np.clip(np.searchsorted(x,xs,side='right')-1,0,m-2)
    t=(xs-x[i])/h[i]
    ys=((2*t**3-3*t**2+1)*y[i]+(t**3-2*t**2+t)*h[i]*d[i]
        +(-2*t**3+3*t**2)*y[i+1]+(t**3-t**2)*h[i]*d[i+1])
    return xs,ys

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--data',type=Path,default=ROOT/'data_placeholder.csv')
    p.add_argument('--config',type=Path,default=ROOT/'config.json')
    args=p.parse_args()
    cfg=json.loads(args.config.read_text())
    with args.data.open(newline='') as f:
        rows=list(csv.DictReader(f))
    datasets=['OCRVQA','TextVQA','COCO']
    if len(rows)!=84 or set(r['dataset'] for r in rows)!=set(datasets):
        raise ValueError('Expected 28 layers for each of OCRVQA, TextVQA and COCO.')
    plt.rcParams.update({'font.family':'sans-serif','font.sans-serif':['DejaVu Sans'],'font.size':13,
                         'svg.fonttype':'none','pdf.fonttype':42})
    fig,axes=plt.subplots(1,3,figsize=(12,3.38))
    fig.subplots_adjust(left=.021,right=.979,bottom=.205,top=.96,wspace=.0225)
    audit=[]
    for ax,name in zip(axes,datasets):
        rr=sorted([r for r in rows if r['dataset']==name],key=lambda r:int(r['layer']))
        x=np.array([int(r['layer']) for r in rr]); y=np.array([float(r['score']) for r in rr])
        if list(x)!=list(range(1,29)) or not np.isfinite(y).all():
            raise ValueError(f'{name}: require unique layers 1 through 28 and finite scores.')
        full=float(cfg['panels'][name]['full_score'])
        selected=int(cfg['panels'][name]['selected_layer'])
        if not 1<=selected<=28 or not np.isfinite(full):
            raise ValueError('Selected layer must be within 1-28, full score must be finite.')
        # Independent native score scales align each Full reference at 94% of panel height.
        # Override lower_score to freeze the axis scale when comparing figure versions.
        lower=cfg['panels'][name].get('lower_score')
        if lower is None:
            lower=min(float(y.min()),full)-.045*max(float(np.ptp(y)),abs(full)*.05,1)
        if full<=lower or float(y.min())<lower:
            raise ValueError(f'{name}: invalid lower score boundary.')
        upper=lower+(full-lower)/.94
        if float(y.max())>upper:
            raise ValueError(f'{name}: score exceeds plot range; revise lower_score or full_score.')
        ax.set_facecolor(BACKGROUND)
        ax.set_xlim(0,29); ax.set_ylim(lower,upper)
        for frac in [0,.25,.5,.75]:
            ax.axhline(lower+(full-lower)*frac,color=GRID,lw=1,zorder=0)
        for xx in [1,7,14,21,28]:
            ax.axvline(xx,color=GRID,lw=1,zorder=0)
        # One independent dashed reference per axes; gaps between subplots stay blank.
        ax.axhline(full,color=COLOR,ls=(0,(4,3)),lw=1.4,zorder=2)
        # Label is centred on the reference line and masks the dashes it covers.
        ax.text(.012,full,f'Full {full:.1f}',transform=ax.get_yaxis_transform(),
                color=COLOR,fontsize=16,ha='left',va='center',zorder=4,
                bbox=dict(facecolor=BACKGROUND,edgecolor='none',pad=2.2))
        # Curve passes through every layer; PCHIP only replaces straight segments.
        xs,ys=smooth_curve(x,y)
        ax.plot(xs,ys,color=COLOR,lw=2.0,zorder=3)
        ax.plot(x,y,ls='none',marker='o',markersize=4.5,markeredgewidth=0,color=COLOR,zorder=4)
        value=float(y[selected-1])
        ax.vlines(selected,lower,value,color=COLOR,ls=(0,(4,3)),lw=1.4,zorder=2)
        # Annotation is anchored to the chosen layer, below the high-score plateau.
        side=cfg['panels'][name].get('label_side','left')
        if side not in ('left','right'):
            raise ValueError('label_side must be left or right.')
        ha='right' if side=='left' else 'left'
        dx=-7 if side=='left' else 7
        ax.annotate(f'{value:.1f}',(selected,lower+.18*(full-lower)),
                    xytext=(dx,0),textcoords='offset points',ha=ha,va='center',
                    color=COLOR,fontsize=23,fontweight='bold')
        ax.annotate(f'Layer {selected}/28',(selected,lower+.065*(full-lower)),
                    xytext=(dx,0),textcoords='offset points',ha=ha,va='center',
                    color=COLOR,fontsize=16)
        ax.set_xticks([1,28]); ax.set_xticklabels(['1','28'],color=COLOR,fontsize=14,fontweight='bold')
        ax.tick_params(axis='x',length=0,pad=7)
        ax.annotate('Layer',(14.5,0),xycoords=ax.get_xaxis_transform(),xytext=(0,-7),
                    textcoords='offset points',ha='center',va='top',
                    color=COLOR,fontsize=14,fontweight='bold')
        ax.set_yticks([])
        ax.set_xlabel(name,color='#164b69',fontsize=19,fontweight='bold',labelpad=8)
        for s in ax.spines.values(): s.set_visible(False)
        audit.append({'dataset':name,'full_score':full,'selected_layer':selected,'selected_score':value,
                      'lower_score':lower,'upper_score':upper,'full_height_fraction':.94,'points':len(x),
                      'interpolation':'pchip'})
    fig.canvas.draw()
    # Extend each panel background down to the tick labels but stop above the dataset name.
    renderer=fig.canvas.get_renderer()
    for ax in axes:
        ab=ax.get_window_extent(renderer).transformed(fig.transFigure.inverted())
        tl=min(t.get_window_extent(renderer).transformed(fig.transFigure.inverted()).y0
               for t in ax.get_xticklabels())
        xl=ax.xaxis.label.get_window_extent(renderer).transformed(fig.transFigure.inverted())
        top=(tl+xl.y1)/2
        fig.add_artist(Rectangle((ab.x0,top),ab.width,ab.y1-top,transform=fig.transFigure,
                                 facecolor=BACKGROUND,edgecolor='none',zorder=-1))
    out=ROOT/'output';out.mkdir(exist_ok=True)
    fig.savefig(out/'figure03_layers.svg',facecolor='white')
    fig.savefig(out/'figure03_layers.pdf',facecolor='white')
    fig.savefig(out/'figure03_layers.png',dpi=600,facecolor='white')
    (out/'render_audit.json').write_text(json.dumps({'data_status':'Qwen2.5-VL-7B','panels':audit},indent=2))
    print(f'Created SVG, PDF and PNG: {out}')

if __name__=='__main__':main()
